insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('management','legal','PE','extranjeros_constituir_empresa_socios_representante',$k$Perú: extranjeros que constituyen empresa o son socios$k$,$k$Perú reconoce libertad de inversión: personas naturales o jurídicas, nacionales o extranjeras, pueden establecer actividades empresariales (fuente: La Cámara, artículo legal). Un extranjero puede ser socio y representante legal. Si viaja al Perú, según esa fuente basta el pasaporte; si actúa mediante otra persona, debe otorgarle poder consular, que debe legalizarse ante el Ministerio de Relaciones Exteriores y traducirse si está en otro idioma (guía de PromPerú/Invest Peru). La constitución de sociedades se hace por escritura pública e inscripción en SUNARP (plataforma SID), y luego el RUC en SUNAT. Para el RUC de un extranjero se usa carné de extranjería, pasaporte con calidad migratoria que permita generar renta, o documento equivalente; fuentes secundarias indican que una visa de turista no basta: confirmar en SUNAT. Algunas guías privadas dicen que el representante debe ser residente legal; confirmar. Las inversiones extranjeras pueden registrarse en ProInversión para acceder a garantías. Dónde confirmar: gob.pe (SUNARP, SUNAT, ProInversión) y un abogado.$k$,'gob.pe (SUNARP/SUNAT/ProInversión); Invest Peru; La Cámara','https://www.gob.pe/276-inscripcion-al-ruc-para-persona-juridica',$k$Material informativo de fuentes oficiales peruanas y fuentes privadas señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','legal','CO','extranjeros_crear_empresa_nit_inversion_extranjera',$k$Colombia: extranjeros que crean empresa y registro de la inversión extranjera$k$,$k$Según una guía privada (ColombiaTramita), un extranjero puede ejercer el comercio en las mismas condiciones que un colombiano (Código de Comercio, art. 11) y necesita NIT ante la DIAN y documento de identidad (cédula de extranjería o pasaporte); un accionista sin residencia no necesita visa, pero debe nombrar representante legal en Colombia, y los documentos del exterior deben apostillarse. La cédula de extranjería la expide Migración Colombia a titulares de visa de residente o ciertas visas de largo plazo. Si una sociedad extranjera actúa de forma permanente puede hacerlo mediante sucursal (art. 469 y ss. del Código de Comercio, según la Cámara de Comercio de Medellín). El capital que ingresa del exterior es inversión extranjera y se registra ante el Banco de la República; según su sitio oficial, si las divisas se canalizaron por un intermediario del mercado cambiario no hay trámite adicional. El registro da derechos como repatriar capital y remitir utilidades. La inversión puede servir para visa de inversionista. Dónde confirmar: banrep.gov.co, DIAN, Cámara de Comercio, Migración Colombia.$k$,'Banco de la República; Cámara de Comercio de Medellín; guía privada ColombiaTramita','https://banrep.gov.co/politica-monetaria-cambiaria/regulacion-operaciones-cambiarias/inversion-extranjera-colombia-colombiana-exterior',$k$Material informativo del Banco de la República y fuentes privadas señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','legal','PY','extranjeros_inversionista_suace_residencia',$k$Paraguay: inversionista extranjero, SUACE y residencia$k$,$k$El SUACE (MIC) es la ventanilla única para abrir empresa y también gestiona el trámite migratorio del inversionista. Primer paso: la Constancia de Inversionista Extranjero (CIE). Según el MIC y un estudio jurídico (Ferrere), los requisitos mínimos son invertir USD 70.000 (o su equivalente en guaraníes) y crear al menos cinco empleos para mano de obra nacional; la Resolución MIC 1.052/2025 fija un plazo máximo de cinco días hábiles para emitirla y aclara que la categoría aplica solo a personas físicas. Con la constancia se puede solicitar la radicación permanente. En sociedades, para que un socio extranjero integre el Directorio debe contar con carnet de radicación permanente y cédula paraguaya (fuente de prensa del Mercosur). Plazos totales y costos (fuentes secundarias citan unos 3 meses y gastos adicionales): confirmar. Dónde confirmar: mic.gov.py (SUACE, guía de inversionistas extranjeros), Dirección Nacional de Migraciones, y un abogado.$k$,'MIC Paraguay (SUACE); Ferrere','https://www.mic.gov.py/wp-content/uploads/2025/06/GUIA-PARA-INVERSIONISTAS-EXTRANJEROS.pdf',$k$Material informativo del MIC y fuentes profesionales señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','legal','CL','extranjeros_rut_inicio_actividades_sin_residencia',$k$Chile: extranjeros, RUT e inicio de actividades$k$,$k$Según el SII, las personas naturales no residentes, chilenas o no, que quieran obtener identificación fiscal chilena o declarar inicio de actividades deben autorizar a un representante con residencia en Chile. Los no residentes que inviertan o hagan negocios necesitan RUT; para ello el SII usa el formulario 4415 (inicio de actividades para extranjeros sin residencia), que identifica socios y su residencia tributaria. Un extranjero puede dar aviso de inicio de actividades en la medida en que esté habilitado para desarrollar la actividad (agrícola, comercial, industrial, minera o profesional). Un extranjero residente necesita cédula de identidad de extranjero emitida en Chile, y la visa puede limitar lo que puede hacer personalmente. Fuentes privadas citan la Ley 20.848 para decir que no se necesita visa para ser dueño, y la plataforma Tu Empresa en un Día para constituir sociedades: confirmar la norma vigente. Es necesario domicilio tributario en Chile. Dónde confirmar: sii.cl, registrodeempresasysociedades.cl, Servicio Nacional de Migraciones.$k$,'SII; Ministerio de Economía (Tu Empresa en un Día)','https://www.sii.cl/destacados/international_transactions/4563-4593-esp-4580.html',$k$Material informativo del SII y fuentes privadas señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','legal','AR','extranjeros_socios_sas_cdi_representante',$k$Argentina: socios extranjeros, CDI y sociedades extranjeras$k$,$k$Para constituir una SAS ante IGJ, cualquier persona puede iniciar el trámite con CUIT, CUIL o CDI y clave fiscal nivel 2 o superior (argentina.gob.ar). Las normas de la IGJ indican que los miembros extranjeros del órgano de administración deben contar con CDI y designar representante en la República Argentina; los poderes del representante de administradores domiciliados en el exterior se inscriben en el Registro Público. Los socios extranjeros obtienen su CDI ante ARCA (ex AFIP). Las sociedades constituidas en el extranjero pueden actuar en el país o participar en sociedades locales conforme a los arts. 118 y 123 de la Ley 19.550, con requisitos de inscripción (la IGJ publicó cambios en 2025 y 2026: confirmar la resolución vigente). Aplican dictámenes de escribano y contador para sociedades extranjeras. Cada provincia tiene su propio Registro Público. Dónde confirmar: argentina.gob.ar (IGJ, Trámites a Distancia), ARCA y un escribano.$k$,'argentina.gob.ar (IGJ); Boletín Oficial','https://www.argentina.gob.ar/node/422143',$k$Material informativo de fuentes oficiales argentinas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','legal','BR','estrangeiro_socio_procurador_cpf_visto',$k$Brasil: extranjeros socios, CPF, procurador y visa$k$,$k$Fuentes profesionales (Contabilizei, Migalhas, Jornal Contábil) coinciden en que un extranjero no residente puede ser socio de una empresa brasileña si obtiene CPF y nombra un procurador residente en Brasil mediante procuración pública traducida, que lo representa ante Receita Federal y Banco Central. Hay una contradicción entre fuentes: Contabilizei indica que el no residente no puede ser administrador, mientras Wise afirma que puede serlo desde 2021; confirmar con la Junta Comercial y un abogado. Un extranjero residente debe comprobar su visa o autorización de residencia (RNM) en la Junta Comercial. Para visa de inversionista, las fuentes citan montos distintos (R$ 150 mil según Jornal Contábil y R$ 500 mil según Contabilivre): no usar ninguna cifra sin confirmar con Polícia Federal/Migração. Ciudadanos del Mercosur con residencia temporal de al menos dos años pueden ser socios o administradores, según Jornal Contábil. Algunos objetos sociales tienen restricciones para extranjeros. Dónde confirmar: Junta Comercial del estado, Receita Federal, Banco Central (registro de capital extranjero) y un abogado.$k$,'Fuentes profesionales brasileñas; Consejería Laboral de España en Brasil','https://www.mites.gob.es/mundo/consejerias/brasil/ficheros/CREAR_EMPRESA_EN_BRASIL.pdf',$k$Material informativo de fuentes profesionales y una guía oficial española, con contradicciones señaladas en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','legal','MX','extranjeros_ley_inversion_extranjera_rnie',$k$México: inversión extranjera, permiso de la SE y RNIE$k$,$k$La Ley de Inversión Extranjera y su Reglamento regulan la participación de extranjeros; el Registro Nacional de Inversiones Extranjeras (RNIE) depende de la Secretaría de Economía. El reglamento define mayoría de capital extranjero como más de 49 % del capital social. Para constituir una sociedad mexicana la Ventanilla Única de la SE muestra un trámite que incluye permiso de uso de denominación, acta constitutiva ante fedatario, inscripción en el RFC (SAT) e inscripción de la sociedad con inversión extranjera en el RNIE. Para sociedades extranjeras que se establecen en México se requiere autorización de la SE (arts. 17 y 17-A de la ley). Algunas actividades tienen restricciones o requieren resolución de la Comisión Nacional de Inversiones Extranjeras: confirmar según el giro. Un extranjero debe acreditar su legal estancia para actuar en el país. Costos y plazos del registro público: según la SE, hay tarifas publicadas (ejemplo MXN 2,302 en 2025); confirmar. Dónde confirmar: ventanillaunica.economia.gob.mx, rnie.economia.gob.mx y un notario.$k$,'Secretaría de Economía (Ventanilla Única, RNIE)','https://ventanillaunica.economia.gob.mx/procedure/339?l=en',$k$Material informativo de la Secretaría de Economía de México; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','legal','EC','extranjeros_socios_scvs_informacion_domiciliacion',$k$Ecuador: socios extranjeros, información a la SCVS y domiciliación$k$,$k$La constitución electrónica de compañías (SCVS, gob.ec) está disponible para personas naturales extranjeras y jurídicas; para un socio persona jurídica extranjera se pide certificado de existencia legal del país de origen y lista completa de socios certificada ante notario y apostillada. Tras constituirse, la compañía debe informar a la Superintendencia sobre socios o accionistas extranjeros: 15 días si se crean por aumento de capital o transferencia de acciones, y anualmente hasta el 5 de febrero si tuvo socios extranjeros durante el año. Una compañía extranjera que quiera operar debe domiciliarse (sucursal) con permiso de operación, poder a favor de un representante legal en Ecuador y luego RUC y patente municipal. Una guía privada menciona capital mínimo de USD 400 para compañías con socios extranjeros y requisitos de visa: dato no oficial, confirmar. Dónde confirmar: gob.ec/scvs, SRI, Ministerio de Relaciones Exteriores (visas) y un abogado.$k$,'gob.ec (Superintendencia de Compañías, Valores y Seguros)','https://www.gob.ec/scvs/tramites/constitucion-electronica-companias',$k$Material informativo de la SCVS y fuentes privadas señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','legal','UY','extranjeros_empresa_extranjera_inscripcion_dgi',$k$Uruguay: empresas y socios extranjeros, inscripción en DGI$k$,$k$Uruguay permite propiedad extranjera de hasta el 100 % según fuentes privadas (Biz Latin Hub); confirmar con un abogado. El portal oficial gub.uy tiene trámites separados de inscripción en DGI/BPS según el caso: empresa extranjera con establecimiento permanente, sucursal de empresa extranjera, empresa extranjera integrante de una sociedad uruguaya, por venta de acciones exclusivamente, propietaria de inmuebles exclusivamente o actividad accidental sin establecimiento permanente. La mayoría se inicia en línea en la DGI (trámite RUT) y se finaliza con cita presencial. Para formar una SAS, el Registro la inscribe y comunica RUT en DGI y número de empresa en BPS. Fuentes privadas mencionan domicilio fiscal en Uruguay y representante residente, y requisitos para abrir cuenta bancaria (como tener empleado en el país): confirmar con el banco. Dónde confirmar: gub.uy/tramites, DGI, Dirección General de Registros y un abogado.$k$,'gub.uy (Trámites DGI y Registros)','https://www.gub.uy/tramites/inscripcion-empresa-extranjera-establecimiento-permanente',$k$Material informativo de fuentes oficiales uruguayas y fuentes privadas señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft');